function findHeading(markdown, headingRe) {
  const m = headingRe.exec(markdown);
  if (!m) return null;
  return { index: m.index, length: m[0].length };
}

function sliceSection(markdown, headingRe) {
  const start = findHeading(markdown, headingRe);
  if (!start) return "";
  const afterStart = markdown.slice(start.index + start.length);
  const next = /^(##)\s+.+\s*$/m.exec(afterStart);
  const endIdx = next ? start.index + start.length + next.index : markdown.length;
  return markdown.slice(start.index, endIdx);
}

function parseLedgerBlock(block) {
  const lines = block.split("\n");
  const transactionId = lines[0].trim();
  if (!/^TXN-[0-9a-f-]+$/i.test(transactionId)) return null;

  const row = {
    transaction_id: transactionId,
    amount: null,
    owner: "",
    status: "",
    date: "",
    provisional: false,
  };

  for (const line of lines.slice(1)) {
    const trimmed = line.trim();
    let m;
    if ((m = /^amount:\s*(.+)\s*$/i.exec(trimmed))) {
      row.amount = Number(m[1]);
    } else if ((m = /^owner:\s*(.+)\s*$/i.exec(trimmed))) {
      row.owner = m[1].trim();
    } else if ((m = /^status:\s*(.+)\s*$/i.exec(trimmed))) {
      row.status = m[1].trim().toLowerCase();
    } else if ((m = /^date:\s*(\d{4}-\d{2}-\d{2})\s*$/i.exec(trimmed))) {
      row.date = m[1];
    } else if ((m = /^provisional:\s*(true|false)\s*$/i.exec(trimmed))) {
      row.provisional = m[1].toLowerCase() === "true";
    }
  }

  return row;
}

function parseLedger(markdown) {
  // Must use ONLY the section whose heading line is exactly:
  //   "## Transaction Ledger"
  const section = sliceSection(markdown, /^##\s+Transaction Ledger\s*$/m);
  if (!section) return [];

  const blocks = section.split(/^###\s+/m).slice(1);
  const byId = new Map();
  for (const block of blocks) {
    const row = parseLedgerBlock(block);
    if (!row) continue;
    if (row.provisional) continue;
    // Keep the last non-provisional block in file order.
    byId.set(row.transaction_id, row);
  }

  return [...byId.values()];
}

module.exports = { parseLedger };
