    if (!cur || String(notice.effective) > String(cur.effective)) {
      winnersByKey.set(key, notice);
    }
  }

  const winningNotices = [...winnersByKey.values()].sort((a, b) =>
    String(a.notice_id).localeCompare(String(b.notice_id)),
  );

  const report = [];
  const correctionChangedStatus = new Set();

  for (const notice of winningNotices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    const field = notice.field;
    const prevVal =
      field === "owner"
        ? target.owner
        : field === "status"
          ? String(target.status).toLowerCase()
          : field === "date"
            ? target.date
            : target[field];

    const newVal = notice.value;
    if (field === "owner") {
      target.owner = newVal;
    } else if (field === "status") {
      target.status = String(newVal).toLowerCase();
      correctionChangedStatus.add(target.transaction_id);
    } else if (field === "date") {
      target.date = newVal;
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field,
      previous_value: prevVal === undefined ? "" : String(prevVal),
      new_value: String(newVal),
      effective: notice.effective,
    });
  }

  // Effective date output rule
  const effectiveOverrideByTxn = new Map();
  for (const r of report) {
    if (r.field === "status" || r.field === "date") {
      effectiveOverrideByTxn.set(r.transaction_id, r.effective);
    }
  }

  const items = sortByTransactionId(
    [...byId.values()].map((row) => {
      const txnId = row.transaction_id;
      const status = String(row.status).toLowerCase();
      const amount = Number(row.amount);

      const reasons = [];
      if (amount > 10000) reasons.push("over_limit");

      const seen = complianceEmailSeen.get(txnId);
      if (status === "rejected" && seen?.any && seen?.anyWithSent) {
        reasons.push("compliance_hold");
      }

      const pex = parsed.policyExceptions instanceof Map ? parsed.policyExceptions.get(txnId) : null;
      if (status === "approved" && amount > 10000 && pex && pex.approved_by === "compliance") {
        reasons.push("policy_waiver");
      }

      if (status === "reversed" && amount > 5000 && correctionChangedStatus.has(txnId)) {
        reasons.push("retroactive_review");
      }

      reasons.sort();
      const exception_reason = reasons.length ? reasons.join(";") : null;

      return {
        transaction_id: txnId,
        owner: row.owner,
        status,
        effective_date: effectiveOverrideByTxn.get(txnId) || row.date,
        amount_usd: Number(amount.toFixed(2)),
        exception_reason,
      };
    }),
  );

  report.sort((a, b) => String(a.notice_id).localeCompare(String(b.notice_id)));
  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
