+function sliceSection(markdown, headingRe) {
+  const start = findHeading(markdown, headingRe);
+  if (!start) return "";
+  const afterStart = markdown.slice(start.index + start.length);
+  const next = /^(##)\s+.+\s*$/m.exec(afterStart);
+  const endIdx = next ? start.index + start.length + next.index : markdown.length;
+  return markdown.slice(start.index, endIdx);
+}
+
+function parseLedgerBlock(block) {
+  const lines = block.split("\n");
+  const transactionId = lines[0].trim();
+  if (!/^TXN-[0-9a-f-]+$/i.test(transactionId)) return null;
+
+  const row = {
