+const { sortByTransactionId } = require("../utils/sort");
+
+const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };
+
+function maxStatus(a, b) {
+  const sa = String(a || "").toLowerCase();
+  const sb = String(b || "").toLowerCase();
+  if (!(sa in STATUS_ORDER)) return sb;
+  if (!(sb in STATUS_ORDER)) return sa;
+  return STATUS_ORDER[sb] >= STATUS_ORDER[sa] ? sb : sa;
+}
+
+function reconcileTransactions(parsed) {
+  // 1) Base ledger (already canonicalized by parser/ledger.js)
+  const byId = new Map();
+  for (const row of parsed.ledger) {
+    byId.set(row.transaction_id, { ...row });
+  }
+
+  // 2) Signed amendments (owner)
+  for (const meeting of parsed.meetings) {
+    if (!meeting || !meeting.transaction_id) continue;
+    if (!meeting.signed) continue;
+    const target = byId.get(meeting.transaction_id);
+    if (!target) continue;
+    if (meeting.effective && meeting.effective < target.date) continue;
+    if (meeting.owner) target.owner = meeting.owner;
+  }
+
+  // 3) Email excerpts (status upgrades only)
+  const complianceEmailSeen = new Map(); // txn -> { any: bool, anyWithSent: bool }
+  for (const email of parsed.emails) {
+    const txnId = email.transaction_id;
+    if (!txnId) continue;
+    const target = byId.get(txnId);
+    if (!target) continue;
+
+    const from = String(email.from_addr || "");
+    const isCompliance = /compliance@/i.test(from);
+    if (!isCompliance) continue;
+
+    const sentOk = email.sent ? email.sent >= target.date : true;
+    if (!sentOk) continue;
+
+    // Track compliance email presence for compliance_hold exception.
+    const prev = complianceEmailSeen.get(txnId) || { any: false, anyWithSent: false };
+    prev.any = true;
+    if (email.has_sent) prev.anyWithSent = true;
+    complianceEmailSeen.set(txnId, prev);
+
+    // Apply only if status moves up the precedence ladder.
+    const before = String(target.status || "").toLowerCase();
+    const after = String(email.status || "").toLowerCase();
+    if (!(after in STATUS_ORDER)) continue;
+    const upgraded = maxStatus(before, after);
+    if (upgraded !== before) target.status = upgraded;
+  }
+
+  // 4) Correction notices last: winner is lexicographically greatest effective per txn+field
+  const winnersByKey = new Map();
+  for (const notice of parsed.corrections) {
+    if (!notice || !notice.transaction_id || !notice.field || !notice.effective) continue;
+    const key = `${notice.transaction_id}::${notice.field}`;
+    const cur = winnersByKey.get(key);
+    if (!cur || String(notice.effective) > String(cur.effective)) {
+      winnersByKey.set(key, notice);
+    }
+  }
+
+  // Apply winners in notice_id order for deterministic previous_value and reporting.
+  const winningNotices = [...winnersByKey.values()].sort((a, b) =>
+    String(a.notice_id).localeCompare(String(b.notice_id)),
+  );
+
+  const report = [];
+  const correctionChangedStatus = new Set();
+
+  for (const notice of winningNotices) {
+    const target = byId.get(notice.transaction_id);
+    if (!target) continue;
+
+    const field = notice.field;
+    const prevVal =
+      field === "owner"
+        ? target.owner
+        : field === "status"
+          ? String(target.status).toLowerCase()
+          : field === "date"
+            ? target.date
+            : target[field];
+
+    const newVal = notice.value;
+    if (field === "owner") {
+      target.owner = newVal;
+    } else if (field === "status") {
+      target.status = String(newVal).toLowerCase();
+      correctionChangedStatus.add(target.transaction_id);
+    } else if (field === "date") {
+      target.date = newVal;
+    }
+
+    report.push({
+      notice_id: notice.notice_id,
+      transaction_id: notice.transaction_id,
+      field,
+      previous_value: prevVal === undefined ? "" : String(prevVal),
+      new_value: String(newVal),
+      effective: notice.effective,
+    });
+  }
+
+  // Effective date output rule: start from ledger date; if a winning correction modifies
+  // status or date, effective_date becomes that notice's effective date.
+  const effectiveOverrideByTxn = new Map();
+  for (const r of report) {
+    if (r.field === "status" || r.field === "date") {
