function parseMeetings(markdown) {
  const meetings = [];
  const re = /^#### Amendment for (TXN-[0-9a-f-]+)\s*$/gim;
  let match;
  while ((match = re.exec(markdown)) !== null) {
    const after = markdown.slice(match.index);
    const next = /^####\s+Amendment for TXN-[0-9a-f-]+\s*$|^##\s+/gim;
    next.lastIndex = match[0].length;
    const nm = next.exec(after);
    const block = nm ? after.slice(0, nm.index) : after;

    const ownerMatch = block.match(/^owner:\s*(.+)$/im);
    const signedMatch = block.match(/^signed:\s*(.+)$/im);
    const effectiveMatch = block.match(/^effective:\s*(\d{4}-\d{2}-\d{2})\s*$/im);

    meetings.push({
